diff --git a/packages/database/features/sharedNodeRoundTrip.feature b/packages/database/features/sharedNodeRoundTrip.feature
new file mode 100644
index 00000000..0174daed
--- /dev/null
+++ b/packages/database/features/sharedNodeRoundTrip.feature
@@ -0,0 +1,23 @@
+Feature: Shared node round trip
+  User story:
+  * As a user of the Roam plugin
+  * I want a node another space published to read back through discovery as it was published
+  * So that the publish and discovery sides of sharing can't drift apart unnoticed
+
+  Acceptance criteria:
+  * The example Roam node, written with the shared converters, reads back through discovery with the same
+  direct content, full content, node type and source identity
+
+  Background:
+    Given the database is blank
+    And the user maparent opens the Roam plugin in space MAPLab
+    And the user user2 opens the Roam plugin in space s2
+    And user of space MAPLab creates group g1
+    And user of space MAPLab adds space s2 to group g1
+    And SpaceAccess are added to the database:
+      | _account_uid | _space_id | permissions |
+      | g1           | MAPLab    | reader      |
+
+  Scenario: The example Roam node reads back as it was published
+    When user maparent publishes the example Roam node to space MAPLab
+    Then a user logged in space s2 reads the example Roam node of space MAPLab back through discovery
diff --git a/packages/database/features/step-definitions/stepdefs.ts b/packages/database/features/step-definitions/stepdefs.ts
index 90ef71f3..4c079e03 100644
--- a/packages/database/features/step-definitions/stepdefs.ts
+++ b/packages/database/features/step-definitions/stepdefs.ts
@@ -13,6 +13,13 @@ import {
 } from "@repo/database/dbTypes";
 import { getVariant, config } from "@repo/database/dbDotEnv";
 import { getConcepts, initNodeSchemaCache } from "@repo/database/lib/queries";
+import {
+  crossAppNodeSchemaToDbConcept,
+  crossAppNodeToDbConcept,
+} from "@repo/database/lib/crossAppConverters";
+import { roamOriginNodeExample } from "@repo/database/crossAppNodeContract.example";
+import { getSharedNodeByRid } from "@repo/database/lib/sharedNodes";
+import { spaceUriAndLocalIdToRid } from "@repo/database/lib/rid";

 import {
   spaceAnonUserEmail,
@@ -927,3 +934,98 @@ When(
     assert.equal(r2.error, null);
   },
 );
+
+When(
+  "user {word} publishes the example Roam node to space {word}",
+  async (userName: string, spaceName: string) => {
+    const localRefs = (world.localRefs || {}) as LocalRefsType;
+    const spaceId = localRefs[spaceName];
+    if (typeof spaceId !== "number") assert.fail("spaceId not a number");
+    const node = roamOriginNodeExample;
+    const client = await getLoggedinDatabaseForUsername(userName);
+    const response = await client.rpc("upsert_concepts", {
+      v_space_id: spaceId,
+      data: [
+        crossAppNodeSchemaToDbConcept({
+          localId: node.nodeType,
+          label: "Claim",
+          format: "[[CLM]] - {content}",
+          authorId: node.authorId,
+          createdAt: node.createdAt,
+          modifiedAt: node.modifiedAt,
+        }),
+        crossAppNodeToDbConcept(node),
+      ],
+    });
+    assert.equal(response.error, null);
+    assert.deepEqual(
+      response.data?.filter((id) => id < 0),
+      [],
+    );
+  },
+);
+
+Then(
+  "a user logged in space {word} reads the example Roam node of space {word} back through discovery",
+  async (readerSpaceName: string, publisherSpaceName: string) => {
+    const localRefs = (world.localRefs || {}) as LocalRefsType;
+    const readerSpaceId = localRefs[readerSpaceName];
+    const publisherSpaceId = localRefs[publisherSpaceName];
+    if (typeof readerSpaceId !== "number")
+      assert.fail("readerSpaceId not a number");
+    if (typeof publisherSpaceId !== "number")
+      assert.fail("publisherSpaceId not a number");
+    const publisherSpace = await getServiceClient()
+      .from("Space")
+      .select("url")
+      .eq("id", publisherSpaceId)
+      .single();
+    assert.equal(publisherSpace.error, null);
+    assert.ok(publisherSpace.data, `space ${publisherSpaceName} not found`);
+    const published = roamOriginNodeExample;
+    const rid = spaceUriAndLocalIdToRid(
+      publisherSpace.data.url,
+      published.localId,
+      "note",
+    );
+    const client = await getLoggedinDatabase(readerSpaceId);
+    const discovered = await getSharedNodeByRid({ client, rid });
+    assert.ok(discovered, `${rid} is not visible through discovery`);
+    const { node, space } = discovered;
+    assert.deepEqual(
+      {
+        rid: node.rid,
+        localId: node.localId,
+        authorId: node.authorId,
+        nodeType: node.nodeType,
+        coreTitle: node.coreTitle,
+        direct: node.content.direct.value,
+        createdAt: node.createdAt,
+        modifiedAt: node.modifiedAt,
+      },
+      {
+        rid,
+        localId: published.localId,
+        authorId: published.authorId,
+        nodeType: published.nodeType,
+        coreTitle: published.coreTitle,
+        direct: published.content.direct.value,
+        createdAt: published.createdAt,
+        modifiedAt: published.modifiedAt,
+      },
+    );
+    const full = await client
+      .from("my_contents")
+      .select("text, content_type")
+      .eq("space_id", space.id)
+      .eq("source_local_id", node.localId)
+      .eq("variant", "full")
+      .eq("original", true)
+      .maybeSingle();
+    assert.equal(full.error, null);
+    assert.deepEqual(full.data, {
+      text: published.content.full?.value,
+      content_type: published.content.full?.contentType,
+    });
+  },
+);
