  8	  CrossAppRelation,
  9	} from "../crossAppContracts";
 10	import { LocalContentDataInput, LocalConceptDataInput } from "../inputTypes";
 11	import { ridToSpaceUriAndLocalId } from "./rid";
 12	import { Enums, CompositeTypes } from "../dbTypes";
 13	
 14	type InlineEmbeddingInput = CompositeTypes<"inline_embedding_input">;
 15	
 16	const crossAppEmbeddingToDbEmbedding = (
 17	  embedding: CrossAppEmbedding | undefined,
 18	): InlineEmbeddingInput | undefined =>
 19	  embedding === undefined
 20	    ? undefined
 21	    : {
 22	        vector: embedding.value,
 23	        model: embedding.embedding || "openai_text_embedding_3_small_1536",
 24	      };
 25	
 26	const filterUndefined = <T extends Record<string, unknown>>(data: T): T => {
 27	  return Object.fromEntries(
 28	    Object.entries(data).filter(([, v]) => v !== undefined),
 29	  ) as T;
 30	};
 31	
 32	const filterUndefinedArray = <T>(data: (T | undefined)[]): T[] =>
 33	  data.filter((v) => v !== undefined);
 34	
 35	const inlineCrossAppContentToDbContent = (
 36	  content: InlineCrossAppContent | undefined,
 37	  variant: Enums<"ContentVariant">,
 38	): LocalContentDataInput | undefined => {
 39	  if (content === undefined) return undefined;
 40	  return filterUndefined<LocalContentDataInput>({
 41	    source_local_id: content.localId,
 42	    text: content.value,
 43	    scale: content.scale || "document",
 44	    content_type: content.contentType || "text/plain",
 45	    variant,
 46	    created: content.createdAt?.toISOString(),
 47	    last_modified: content.modifiedAt?.toISOString(),
 48	    author_local_id: content.authorId,
 49	    embedding_inline: crossAppEmbeddingToDbEmbedding(content.embedding),
 50	  });
 51	};
 52	
 53	export const crossAppNodeToDbContent = (
 54	  node: CrossAppNode | undefined,
 55	  variant: "full" | "direct",
 56	): LocalContentDataInput | undefined => {
 57	  if (node === undefined) return undefined;
 58	  const content = node.content[variant];
 59	  if (content === undefined) return undefined;
 60	  return inlineCrossAppContentToDbContent(
 61	    {
 62	      ...content,
 63	      createdAt: content.createdAt || node.createdAt,
 64	      modifiedAt: content.modifiedAt || node.modifiedAt,
 65	      authorId: content.authorId || node.authorId,
 66	    },
 67	    variant,
 68	  );
 69	};
 70	
 71	export const crossAppNodeToDbConcept = (
 72	  node: CrossAppNode,
 73	): LocalConceptDataInput => {
 74	  const spaceUri = node.rid
 75	    ? ridToSpaceUriAndLocalId(node.rid).spaceUri
 76	    : undefined;
 77	  return filterUndefined<LocalConceptDataInput>({
 78	    space_url: spaceUri,
 79	    source_local_id: node.localId,
 80	    name: node.content.direct.value,
 81	    author_local_id: node.authorId,
 82	    schema_represented_by_local_id: node.nodeType,
 83	    literal_content: {
 84	      core_title: node.coreTitle,
 85	    },
 86	    contents_inline: filterUndefinedArray([
 87	      crossAppNodeToDbContent(node, "direct"),
 88	      crossAppNodeToDbContent(node, "full"),
 89	    ]),
 90	    created: node.createdAt?.toISOString(),
 91	    last_modified: node.modifiedAt?.toISOString(),
 92	    local_reference_content: node.slots,
 93	  });
 94	};
 95	
 96	export const crossAppNodeSchemaToDbConcept = (
 97	  node: CrossAppNodeSchema,
 98	): LocalConceptDataInput => {
 99	  const slots = Object.keys(node.slotDefinitions ?? {});
100	  const literalInfo = filterUndefined({
101	    label: node.label,
102	    template: node.templateTitle,
103	    template_content: node.template,
104	    format: node.format,
105	    roles: slots.length > 0 ? slots : undefined,
106	  });
107	  const referenceContent = slots.length ? node.slotDefinitions : undefined;
108	  const spaceUri = node.rid
109	    ? ridToSpaceUriAndLocalId(node.rid).spaceUri
110	    : undefined;
111	  return filterUndefined<LocalConceptDataInput>({
112	    space_url: spaceUri,
113	    source_local_id: node.localId,
114	    name: node.label,
115	    author_local_id: node.authorId,
116	    is_schema: true,
117	    literal_content:
118	      Object.keys(literalInfo).length > 0 ? literalInfo : undefined,
119	    local_reference_content: referenceContent,
120	    created: node.createdAt?.toISOString(),
121	    last_modified: node.modifiedAt?.toISOString(),
122	  });
123	};
124	
125	export const crossAppRelationTypeSchemaToDbConcept = (
126	  node: CrossAppRelationTypeSchema,
127	): LocalConceptDataInput => {
128	  const spaceUri = node.rid
129	    ? ridToSpaceUriAndLocalId(node.rid).spaceUri
130	    : undefined;
131	  return filterUndefined<LocalConceptDataInput>({
132	    space_url: spaceUri,
133	    source_local_id: node.localId,
134	    name: node.label,
135	    author_local_id: node.authorId,
136	    is_schema: true,
137	    literal_content: {
138	      roles: ["source", "destination"],
139	      label: node.label,
140	      complement: node.complement,
141	    },
142	    created: node.createdAt?.toISOString(),
143	    last_modified: node.modifiedAt?.toISOString(),
144	  });
145	};
146	
147	export const crossAppRelationTripleSchemaToDbConcept = (
148	  node: CrossAppRelationTripleSchema,
149	  // used in Obsidian, not yet in Roam.
150	  relationType?: CrossAppRelationTypeSchema,
151	): LocalConceptDataInput | undefined => {
152	  if (!("label" in node) && relationType === undefined) return undefined;
153	  const label = "label" in node ? node.label : relationType!.label;
154	  const complement =
155	    "complement" in node ? node.complement : relationType!.complement;
156	  const spaceUri = node.rid
157	    ? ridToSpaceUriAndLocalId(node.rid).spaceUri
158	    : undefined;
159	  return filterUndefined<LocalConceptDataInput>({
160	    space_url: spaceUri,
161	    source_local_id: node.localId,
162	    name: node.localId, // has to be unique within space. Not seen yet.
163	    author_local_id: node.authorId,
164	    is_schema: true,
165	    literal_content: filterUndefined({
166	      roles: ["source", "destination"],
167	      label,
168	      complement,
169	    }),
170	    local_reference_content: {
171	      relation_type: node.relation,
172	      source: node.sourceType,
173	      destination: node.destinationType,
174	    },
175	    created: node.createdAt?.toISOString(),
176	    last_modified: node.modifiedAt?.toISOString(),
177	  });
178	};
179	
180	export const crossAppRelationToDbConcept = (
181	  node: CrossAppRelation,
182	): LocalConceptDataInput => {
183	  const spaceUri = node.rid
184	    ? ridToSpaceUriAndLocalId(node.rid).spaceUri
185	    : undefined;
186	  return filterUndefined<LocalConceptDataInput>({
187	    // use LocalIds... not ideal
188	    name: `${node.localId}: ${node.source} -${node.relationType}-> ${node.destination}`,
189	    space_url: spaceUri,
190	    source_local_id: node.localId,
191	    author_local_id: node.authorId,
192	    schema_represented_by_local_id: node.relationType,
193	    local_reference_content: {
194	      source: node.source,
195	      destination: node.destination,
196	    },
197	    created: node.createdAt?.toISOString(),
198	    last_modified: node.modifiedAt?.toISOString(),
199	  });
200	};

