content.content:
  1	import type { DGSupabaseClient } from "./client";
  2	import { ridToSpaceUriAndLocalId, spaceUriAndLocalIdToRid } from "./rid";
  3	import {
  4	  dbNodesToCrossApp,
  5	  type DbCrossAppNode,
  6	  type DbNodeConcept,
  7	  type DbNodeRows,
  8	} from "./dbToCrossAppConverters";
  9	import type { Enums, Tables } from "../dbTypes";
 10	
 11	type SharedSpace = Pick<
 12	  Tables<"my_spaces">,
 13	  "id" | "name" | "platform" | "url"
 14	>;
 15	type Platform = Enums<"Platform">;
 16	
 17	export type SharedNodeSpace = {
 18	  id: number;
 19	  name: string;
 20	  platform: Platform;
 21	  url: string;
 22	};
 23	
 24	export type SharedNodeListing = {
 25	  nodes: DbCrossAppNode[];
 26	  spaces: Record<string, SharedNodeSpace>;
 27	};
 28	
 29	export type SharedNodeRows = DbNodeRows & {
 30	  spaces: SharedSpace[];
 31	};
 32	
 33	const CONCEPT_COLUMNS_WITH_SLOTS =
 34	  "core_title:literal_content->>core_title, is_schema, last_modified, schema_id, source_local_id, space_id, reference_content, concepts_of_relation(id, space_id, source_local_id)";
 35	const DIRECT_CONTENT_COLUMNS =
 36	  "author_id, created, last_modified, source_local_id, space_id, text, variant";
 37	const FULL_CONTENT_SUMMARY_COLUMNS = "last_modified, source_local_id, space_id";
 38	const SPACE_COLUMNS = "id, name, platform, url";
 39	
 40	const getValidSpaces = (spaces: SharedSpace[]): SharedNodeSpace[] =>
 41	  spaces.flatMap((space): SharedNodeSpace[] => {
 42	    if (
 43	      typeof space.id !== "number" ||
 44	      typeof space.name !== "string" ||
 45	      space.platform === null ||
 46	      typeof space.url !== "string"
 47	    )
 48	      return [];
 49	    return [
 50	      {
 51	        id: space.id,
 52	        name: space.name,
 53	        platform: space.platform,
 54	        url: space.url,
 55	      },
 56	    ];
 57	  });
 58	
 59	const getAssociatedSpaces = async ({
 60	  client,
 61	  concepts,
 62	  currentSpace,
 63	  currentSpaceId,
 64	}: {
 65	  client: DGSupabaseClient;
 66	  concepts: DbNodeConcept[];
 67	  currentSpace?: SharedSpace;
 68	  currentSpaceId?: number;
 69	}): Promise<SharedSpace[]> => {
 70	  const associatedSpaceIds = new Set(
 71	    [
 72	      ...concepts.map((cpt) => cpt.space_id),
 73	      ...concepts.flatMap((cpt) =>
 74	        cpt.concepts_of_relation.map((cr) => cr.space_id),
 75	      ),
 76	    ].filter((id) => id !== null),
 77	  );
 78	  if (currentSpace !== undefined) {
 79	    currentSpaceId = currentSpace.id ?? currentSpaceId;
 80	  } else if (currentSpaceId !== undefined)
 81	    associatedSpaceIds.add(currentSpaceId);
 82	  const spaces: SharedSpace[] = [];
 83	  if (currentSpace !== undefined && currentSpaceId !== undefined) {
 84	    spaces.push(currentSpace);
 85	    associatedSpaceIds.delete(currentSpaceId);
 86	  }
 87	  if (associatedSpaceIds.size > 0) {
 88	    const { data, error } = await client
 89	      .from("my_spaces")
 90	      .select(SPACE_COLUMNS)
 91	      .in("id", [...associatedSpaceIds]);
 92	    if (error) throw error;
 93	    spaces.push(...data);
 94	  }
 95	  return spaces;
 96	};
 97	
 98	const getSharedNodeRows = async ({
 99	  client,
100	  currentSpaceId,
101	}: {
102	  client: DGSupabaseClient;
103	  currentSpaceId: number;
104	}): Promise<SharedNodeRows> => {
105	  const [conceptsResponse, directResponse, fullResponse] = await Promise.all([
106	    client
107	      .from("my_concepts")
108	      .select(CONCEPT_COLUMNS_WITH_SLOTS)
109	      .neq("space_id", currentSpaceId)
110	      .eq("is_schema", false)
111	      .eq("is_relation", false),
112	    client
113	      .from("my_contents")
114	      .select(DIRECT_CONTENT_COLUMNS)
115	      .neq("space_id", currentSpaceId)
116	      .eq("variant", "direct"),
117	    client
118	      .from("my_contents")
119	      .select(FULL_CONTENT_SUMMARY_COLUMNS)
120	      .neq("space_id", currentSpaceId)
121	      .eq("variant", "full"),
122	  ]);
123	  if (conceptsResponse.error) throw conceptsResponse.error;
124	  if (directResponse.error) throw directResponse.error;
125	  if (fullResponse.error) throw fullResponse.error;
126	  const spaces = await getAssociatedSpaces({
127	    client,
128	    concepts: conceptsResponse.data,
129	    currentSpaceId,
130	  });
131	
132	  return {
133	    nodes: conceptsResponse.data,
134	    directContents: directResponse.data,
135	    fullContentSummaries: fullResponse.data,
136	    spaces,
137	  };
138	};
139	
140	const toSharedNodeListing = async ({
141	  client,
142	  spaces,
143	  ...rows
144	}: SharedNodeRows & {
145	  client: DGSupabaseClient;
146	}): Promise<SharedNodeListing> => {
147	  const validSpaces = getValidSpaces(spaces);
148	  const nodes = await dbNodesToCrossApp({
149	    client,
150	    ...rows,
151	    spaceMap: Object.fromEntries(validSpaces.map(({ id, url }) => [id, url])),
152	  });
153	  return {
154	    nodes: nodes.sort(
155	      (left, right) =>
156	        right.modifiedAt.getTime() - left.modifiedAt.getTime() ||
157	        left.content.direct.value.localeCompare(right.content.direct.value),
158	    ),
159	    spaces: Object.fromEntries(validSpaces.map((space) => [space.url, space])),
160	  };
161	};
162	
163	export const listGroupSharedNodes = async ({
164	  client,
165	  currentSpaceId,
166	}: {
167	  client: DGSupabaseClient;
168	  currentSpaceId: number;
169	}): Promise<SharedNodeListing> => {
170	  const rows = await getSharedNodeRows({ client, currentSpaceId });
171	  return toSharedNodeListing({ client, ...rows });
172	};
173	
174	export const getSharedNodeSpace = ({
175	  node,
176	  spaces,
177	}: {
178	  node: DbCrossAppNode;
179	  spaces: SharedNodeListing["spaces"];
180	}): SharedNodeSpace => {
181	  const space = spaces[ridToSpaceUriAndLocalId(node.rid).spaceUri];
182	  if (space === undefined) throw new Error(`Missing the space of ${node.rid}`);
183	  return space;
184	};
185	
186	export const getNodeTypeRid = (node: DbCrossAppNode): string =>
187	  spaceUriAndLocalIdToRid(
188	    ridToSpaceUriAndLocalId(node.rid).spaceUri,
189	    node.nodeType,
190	    "schema",
191	  );
192	
193	export const getSharedNodeByRid = async ({
194	  client,
195	  rid,
196	}: {
197	  client: DGSupabaseClient;
198	  rid: string;
199	}): Promise<{ node: DbCrossAppNode; space: SharedNodeSpace } | null> => {
200	  const { spaceUri, sourceLocalId } = ridToSpaceUriAndLocalId(rid);
201	  const spaceResponse = await client
202	    .from("my_spaces")
203	    .select(SPACE_COLUMNS)
204	    .eq("url", spaceUri)
205	    .maybeSingle();
206	  if (spaceResponse.error) throw spaceResponse.error;
207	  const space = spaceResponse.data;
208	  if (!space || typeof space.id !== "number") return null;
209	
210	  const [conceptsResponse, directResponse, fullResponse] = await Promise.all([
211	    client
212	      .from("my_concepts")
213	      .select(CONCEPT_COLUMNS_WITH_SLOTS)
214	      .eq("space_id", space.id)
215	      .eq("source_local_id", sourceLocalId)
216	      .eq("is_schema", false)
217	      .eq("is_relation", false),
218	    client
219	      .from("my_contents")
220	      .select(DIRECT_CONTENT_COLUMNS)
221	      .eq("space_id", space.id)
222	      .eq("source_local_id", sourceLocalId)
223	      .eq("variant", "direct"),
224	    client
225	      .from("my_contents")
226	      .select(FULL_CONTENT_SUMMARY_COLUMNS)
227	      .eq("space_id", space.id)
228	      .eq("source_local_id", sourceLocalId)
229	      .eq("variant", "full"),
230	  ]);
231	  if (conceptsResponse.error) throw conceptsResponse.error;
232	  if (directResponse.error) throw directResponse.error;
233	  if (fullResponse.error) throw fullResponse.error;
234	  const spaces = await getAssociatedSpaces({
235	    client,
236	    concepts: conceptsResponse.data,
237	    currentSpace: space,
238	  });
239	
240	  const listing = await toSharedNodeListing({
241	    client,
242	    nodes: conceptsResponse.data,
243	    directContents: directResponse.data,
244	    fullContentSummaries: fullResponse.data,
245	    spaces,
246	  });
247	  const [node] = listing.nodes;
248	  if (!node) {
249	    if (conceptsResponse.data.length === 0) return null;
